// InputDigest is the canonical SHA-256 of an op input. Canonical form = JSON with
// object keys sorted and no insignificant whitespace (what encoding/json emits for maps).
func InputDigest(input json.RawMessage) (string, error) {
	var v any
	d := json.NewDecoder(bytes.NewReader(input))
	d.UseNumber()
	if err := d.Decode(&v); err != nil {
		return "", fmt.Errorf("input digest: %w", err)
	}
	c, err := json.Marshal(v)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(c)
	return "sha256:" + hex.EncodeToString(sum[:]), nil
}

